-- ==========================================
-- Geração Automática: Mitos e Lendas Tupi (Módulo 3 Agrupado)
-- ==========================================

DELETE FROM progresso_usuario_licao WHERE licao_id IN (SELECT l.id FROM licoes l JOIN modulos m ON l.modulo_id = m.id WHERE m.titulo LIKE 'Módulo 3: Boitatá%' OR m.titulo LIKE 'Módulo 4: Tupã%' OR m.titulo LIKE 'Módulo 5: O Mundo Espiritual%');

DELETE FROM modulos WHERE titulo LIKE 'Módulo 3: Boitatá%';
DELETE FROM modulos WHERE titulo LIKE 'Módulo 4: Tupã%';
DELETE FROM modulos WHERE titulo LIKE 'Módulo 5: O Mundo Espiritual%';

